<?php
declare(strict_types=1);
require_once __DIR__.'/blog-i18n.php';
require_once __DIR__.'/date-time.php';
require_once __DIR__.'/blog-surface.php';
function nodenoBlogEscape(string $value): string {return htmlspecialchars($value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function nodenoBlogUrl(string $slug='',string $locale='tr',array $query=[]): string {
 $q=$locale==='tr'?[]:['lang'=>$locale];$q=array_merge($q,$query);$url='/blog'.($slug!==''?'/'.rawurlencode($slug):'');return $url.($q?'?'.http_build_query($q,'','&',PHP_QUERY_RFC3986):'');
}
function nodenoBlogOrigin():string {return 'https://nodenohome.com';}
function nodenoBlogSourceTitle(array $source,array $copy):string {
 $key=['https://biancastella.com.tr/kartela/'=>'sourceChart','https://biancastella.com.tr/merak-ettikleriniz/'=>'sourceFaq','https://biancastella.com.tr/mobilya/'=>'sourceFurniture','https://biancastella.com.tr/nereye-ne-kadar/'=>'sourceQuantity','https://biancastella.com.tr/uygulama/'=>'sourceApplication','https://www.filliboya.com/ilham-veren-fikirler'=>'sourceInspiration'][$source['url']]??null;
 return $key!==null?$copy[$key]:$source['title'];
}
function nodenoBlogToolForm(string $kind,string $locale):string {
 if($kind==='surface')return nodenoBlogSurfaceForm($locale);
 $c=nodenoBlogCopy($locale);$e='nodenoBlogEscape';$kind=in_array($kind,['space','paint','palette'],true)?$kind:'space';
 $input=static function(string $name,string $label,string $value,string $min='0',string $max='1000',string $step='0.1')use($e):string{return '<label>'.$e($label).'<input type="number" name="'.$name.'" value="'.$value.'" min="'.$min.'" max="'.$max.'" step="'.$step.'" inputmode="decimal" required></label>';};
 $form='<form class="blog-tool" data-blog-tool="'.$kind.'" data-error="'.$e($c['error']).'" data-fits="'.$e($c['fits']).'" data-no-fit="'.$e($c['noFit']).'"><h2>'.$e($c[$kind]).'</h2>';
 if($kind==='space'){$form.='<div class="blog-tool-fields">'.$input('room',$c['room'],'300','1','100000','1').$input('furniture',$c['furniture'],'60','0','100000','1').$input('opposite',$c['opposite'],'45','0','100000','1').'</div><svg data-space-chart viewBox="0 0 620 140" role="img" aria-label="'.$e($c['space']).'"><rect x="30" y="20" width="560" height="70" rx="5" fill="#FFFFFF" stroke="#536770"/><rect data-furniture x="30" y="20" width="112" height="70" rx="5" fill="#172D38"/><rect data-opposite x="506" y="20" width="84" height="70" rx="5" fill="#8A8249"/><text data-gap x="310" y="120" text-anchor="middle" fill="#172D38" font-size="20"></text></svg>';}
 elseif($kind==='paint'){$form.='<div class="blog-tool-fields">'.$input('length',$c['length'],'4','0.01').$input('width',$c['width'],'3','0.01').$input('height',$c['height'],'2.5','0.01','100').$input('openings',$c['openings'],'2','0','100000').$input('coats',$c['coats'],'2','1','10','1').$input('coverage',$c['coverage'],'10','0.01').'<label>'.$e($c['basis']).'<select name="basis"><option value="coat">'.$e($c['coat']).'</option><option value="system">'.$e($c['system']).'</option></select></label>'.$input('waste',$c['waste'],'10','0','100','1').'</div>';}
 else{$form.='<label>'.$e($c['startingColor']).'<input type="color" name="color" value="#8a8249"></label>';}
 return $form.'<button type="submit">'.$e($c['calculate']).'</button><output aria-live="polite" aria-atomic="true"></output><p class="blog-note">'.$e($c[$kind.'Note']).'</p></form>';
}
function nodenoBlogCard(array $a,string $locale):string {
 $e='nodenoBlogEscape';$c=nodenoBlogCopy($locale);$im=$a['image'];return '<article class="blog-card"><a class="blog-card-image" href="'.$e(nodenoBlogUrl($a['slug'],$locale)).'"><img src="'.$e($im['url']).'" width="'.(int)$im['width'].'" height="'.(int)$im['height'].'" alt="'.$e($im['alt']).'" loading="lazy" decoding="async"></a><div class="blog-card-copy"><p class="blog-eyebrow">'.$e($c[$a['category']]??$a['category']).'</p><h2><a href="'.$e(nodenoBlogUrl($a['slug'],$locale)).'">'.$e($a['title']).'</a></h2><p>'.$e($a['description']).'</p><time datetime="'.$e($a['publishedAt']).'">'.$e(nodenoHumanDateTime($a['publishedAt'])).'</time></div></article>';
}
function nodenoBlogPageDocument(string $locale,?array $article,array $published,array $bank,array $query=[],array $pagination=[]):string {
 $locale=in_array($locale,['tr','en','ru','ar'],true)?$locale:'tr';$c=nodenoBlogCopy($locale);$e='nodenoBlogEscape';$origin=nodenoBlogOrigin();$tool=$query['tool']??'';$notFound=($query['_notFound']??false)===true;
 $title=$notFound?$c['notFound']:($article['title']??($tool!==''?($c[$tool]??$c['tools']):(!empty($query['category'])?($c[$query['category']]??$c['name']):$c['name'])));$description=$article['description']??$c['intro'];$slug=$article['slug']??'';
 $routeQuery=[];if(!$article){if($tool!=='')$routeQuery['tool']=$tool;elseif(!empty($query['category']))$routeQuery['category']=$query['category'];if(($pagination['page']??1)>1&&$tool==='')$routeQuery['pg']=(int)$pagination['page'];}
 $canonical=$origin.nodenoBlogUrl($slug,$locale,$routeQuery);$indexable=!$notFound&&empty($query['q'])&&(!empty($published)||$tool!=='');
 $schema=[['@context'=>'https://schema.org','@type'=>$article?'BlogPosting':'CollectionPage','name'=>$title,'description'=>$description,'url'=>$canonical,'inLanguage'=>$locale]];
 if($article){$schema[0]=array_merge($schema[0],['headline'=>$title,'datePublished'=>$article['publishedAt'],'dateModified'=>$article['publishedAt'],'author'=>['@type'=>'Organization','name'=>$c['author']],'publisher'=>['@type'=>'Organization','name'=>'NODENO','logo'=>['@type'=>'ImageObject','url'=>$origin.'/assets/brand/logo-horizontal.svg']],'image'=>['@type'=>'ImageObject','url'=>$origin.$article['image']['url'],'width'=>$article['image']['width'],'height'=>$article['image']['height']],'mainEntityOfPage'=>$canonical,'keywords'=>implode(', ',$article['keywords']??[])]);}
 $schema[]=['@context'=>'https://schema.org','@type'=>'BreadcrumbList','itemListElement'=>[['@type'=>'ListItem','position'=>1,'name'=>'NODENO','item'=>$origin.'/'],['@type'=>'ListItem','position'=>2,'name'=>$c['blog'],'item'=>$origin.nodenoBlogUrl('',$locale)],...($article?[['@type'=>'ListItem','position'=>3,'name'=>$title,'item'=>$canonical]]:[])]];
 $nonce=bin2hex(random_bytes(16));$head='<title>'.$e($title).' | NODENO</title><meta name="description" content="'.$e($description).'"><meta name="robots" content="'.($indexable?'index,follow,max-image-preview:large':'noindex,follow').'"><link rel="canonical" href="'.$e($canonical).'"><meta property="og:title" content="'.$e($title).'"><meta property="og:description" content="'.$e($description).'"><meta property="og:type" content="'.($article?'article':'website').'"><meta property="og:url" content="'.$e($canonical).'"><meta name="twitter:card" content="summary_large_image">';
 if($article)$head.='<meta property="og:image" content="'.$e($origin.$article['image']['url']).'">';
 $available=$article['availableLocales']??($article?['tr']:['tr','en','ru','ar']);
 if($indexable)foreach($available as $code)$head.='<link rel="alternate" hreflang="'.$e($code).'" href="'.$e($origin.nodenoBlogUrl($slug,$code,$routeQuery)).'">';
 $head.='<script type="application/ld+json" nonce="'.$nonce.'">'.json_encode($schema,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG).'</script>';
 $languages='';foreach(['tr'=>'TR','en'=>'EN','ru'=>'RU','ar'=>'العربية']as $code=>$label)if(in_array($code,$available,true))$languages.='<a href="'.$e(nodenoBlogUrl($slug,$code,$routeQuery)).'" lang="'.$code.'"'.($code===$locale?' aria-current="page"':'').'>'.$label.'</a>';
 $header='<a class="blog-skip" href="#blog-content">'.$e($c['skip']).'</a><header class="blog-header"><a class="blog-logo" href="/?lang='.$locale.'" aria-label="NODENO"><img src="/wordmark.svg?v=brand-20261112-v3" width="1600" height="480" alt="NODENO"></a><nav aria-label="'.$e($c['blog']).'"><a href="'.$e(nodenoBlogUrl('',$locale)).'">'.$e($c['blog']).'</a><a href="'.$e(nodenoBlogUrl('',$locale,['tool'=>'space'])).'">'.$e($c['tools']).'</a><a href="/?page=catalog&amp;lang='.$locale.'">'.$e($c['shop']).'</a></nav><nav class="blog-languages" aria-label="Language">'.$languages.'</nav></header>';
 $body='';
 if($notFound){$body='<section class="blog-intro"><h1>'.$e($c['notFound']).'</h1><p>'.$e($c['notFoundText']).'</p><a href="'.$e(nodenoBlogUrl('',$locale)).'">'.$e($c['blog']).'</a></section>';}
 elseif($article){
  $a=$article;$body='<div class="blog-breadcrumb"><a href="'.$e(nodenoBlogUrl('',$locale)).'">'.$e($c['blog']).'</a><span>/</span><a href="'.$e(nodenoBlogUrl('',$locale,['category'=>$a['category']])).'">'.$e($c[$a['category']]??$a['category']).'</a></div><article class="blog-article"><header class="blog-article-heading"><p class="blog-eyebrow">'.$e($c[$a['category']]??$a['category']).'</p><h1>'.$e($a['title']).'</h1><p class="blog-deck">'.$e($a['intro']).'</p><p class="blog-byline">'.$e($c['author']).' · '.$e($c['published']).' <time datetime="'.$e($a['publishedAt']).'">'.$e(nodenoHumanDateTime($a['publishedAt'])).'</time></p></header><figure class="blog-article-image"><img src="'.$e($a['image']['url']).'" width="'.(int)$a['image']['width'].'" height="'.(int)$a['image']['height'].'" alt="'.$e($a['image']['alt']).'" fetchpriority="high"><figcaption>'.$e($c['diagram']).'</figcaption></figure><div class="blog-reading-layout"><div class="blog-prose">';
  foreach($a['sections']as $i=>$s){$body.='<section id="section-'.($i+1).'"><h2>'.$e($s['heading']).'</h2>';foreach($s['paragraphs']as $paragraph)$body.='<p>'.$e($paragraph).'</p>';if(!empty($s['list'])){$body.='<ul>';foreach($s['list']as $item)$body.='<li>'.$e($item).'</li>';$body.='</ul>';}$body.='</section>';}
  $body.='<section class="blog-checklist"><h2>'.$e($c['checklist']).'</h2><ul>';foreach($a['checklist']as $item)$body.='<li>'.$e($item).'</li>';$body.='</ul></section>';
  if(!empty($a['products'])){$body.='<section><h2>'.$e($c['shop']).'</h2>';foreach($a['products']as $product)$body.='<a class="blog-product" href="/?product='.$e($product['id']).'&amp;lang='.$locale.'"><img src="'.$e($product['image']).'" alt="'.$e($product['name']).'" loading="lazy" width="180" height="180"><span>'.$e($product['name']).'</span></a>';$body.='</section>';}
  $body.='<section class="blog-sources"><h2>'.$e($c['sources']).'</h2><p>'.$e($c['sourceNote']).'</p><ul>';foreach($a['sources']as $source)$body.='<li><a href="'.$e($source['url']).'" rel="noopener noreferrer">'.$e(nodenoBlogSourceTitle($source,$c)).'</a></li>';$body.='</ul></section></div><aside class="blog-sidebar"><nav aria-label="'.$e($c['toc']).'"><strong>'.$e($c['toc']).'</strong>';foreach($a['sections']as $i=>$s)$body.='<a href="#section-'.($i+1).'">'.$e($s['heading']).'</a>';$body.='</nav>'.nodenoBlogToolForm($a['tool']??'space',$locale).'</aside></div></article>';
  $related=array_values(array_filter($published,static fn($row)=>$row['id']!==$a['id']&&(in_array($row['slug'],$a['related']??[],true)||$row['category']===$a['category'])));if(!$related)$related=array_values(array_filter($published,static fn($row)=>$row['id']!==$a['id']));
  if($related){$body.='<section class="blog-related"><h2>'.$e($c['related']).'</h2><div class="blog-grid">';foreach(array_slice($related,0,3)as $row)$body.=nodenoBlogCard($row,$locale);$body.='</div></section>';}
 }elseif($tool!==''){$body='<section class="blog-intro"><p class="blog-eyebrow">'.$e($c['name']).'</p><h1>'.$e($c['tools']).'</h1><p>'.$e($c['intro']).'</p></section><nav class="blog-tool-nav">';foreach(['space','paint','palette','surface']as $key)$body.='<a href="'.$e(nodenoBlogUrl('',$locale,['tool'=>$key])).'"'.($key===$tool?' aria-current="page"':'').'>'.$e($c[$key]).'</a>';$body.='</nav><div class="blog-tool-page">'.nodenoBlogToolForm($tool,$locale).'</div>';}
 else{
  $body='<section class="blog-intro"><p class="blog-eyebrow">'.$e($c['name']).'</p><h1>'.$e($c['title']).'</h1><p>'.$e($c['intro']).'</p><a class="blog-inline-tool" href="'.$e(nodenoBlogUrl('',$locale,['tool'=>'paint'])).'">'.$e($c['paint']).'</a></section><form class="blog-search" method="get" action="/blog"><label for="blog-search">'.$e($c['search']).'</label><div><input id="blog-search" type="search" name="q" maxlength="120" value="'.$e((string)($query['q']??'')).'"><input type="hidden" name="lang" value="'.$locale.'"><button>'.$e($c['searchButton']).'</button></div></form><nav class="blog-categories" aria-label="'.$e($c['all']).'"><a href="'.$e(nodenoBlogUrl('',$locale)).'"'.(empty($query['category'])?' aria-current="page"':'').'>'.$e($c['all']).'</a>';
  foreach(['small-spaces','entryway','living','bedroom','work','care','planning','color','paint-math','surfaces','application','renewal']as $category)$body.='<a href="'.$e(nodenoBlogUrl('',$locale,['category'=>$category])).'"'.(($query['category']??'')===$category?' aria-current="page"':'').'>'.$e($c[$category]).'</a>';
  $body.='</nav><section class="blog-list"><h2>'.$e(!empty($query['category'])?($c[$query['category']]??$c['latest']):$c['latest']).'</h2>';
  if(!$published)$body.='<p class="blog-empty">'.$e($c['empty']).'</p>';else{$body.='<div class="blog-grid">';foreach($published as $a)$body.=nodenoBlogCard($a,$locale);$body.='</div>';}
  $body.='</section>';if(($pagination['pages']??1)>1){$body.='<nav class="blog-pagination" aria-label="Pagination">';foreach([-1=>'previous',1=>'next']as $delta=>$key){$page=($pagination['page']??1)+$delta;if($page>=1&&$page<=$pagination['pages'])$body.='<a rel="'.($delta===1?'next':'prev').'" href="'.$e(nodenoBlogUrl('',$locale,array_merge(array_intersect_key($query,array_flip(['category','q'])),['pg'=>$page]))).'">'.$e($c[$key]).'</a>';}$body.='</nav>';}
 }
 $footer='<footer class="blog-footer"><a href="/?lang='.$locale.'"><img src="/wordmark.svg?v=brand-20261112-v3" width="1600" height="480" alt="NODENO"></a><nav><a href="/?page=catalog&amp;lang='.$locale.'">'.$e($c['shop']).'</a><a href="'.$e(nodenoBlogUrl('',$locale,['tool'=>'paint'])).'">'.$e($c['tools']).'</a><a href="/blog/feed.xml">'.$e($c['rss']).'</a></nav></footer>';
 return '<!doctype html><html lang="'.$locale.'" dir="'.($locale==='ar'?'rtl':'ltr').'"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'.$head.'<link rel="icon" href="/favicon.svg?v=brand-20261112-v2"><link rel="stylesheet" href="/blog.css?v=20261113-r2"><link rel="alternate" type="application/rss+xml" title="NODENO" href="/blog/feed.xml"><script type="module" src="/blog-tools.js?v=20261113-r2" nonce="'.$nonce.'"></script></head><body>'.$header.'<main id="blog-content" class="blog-wrap">'.$body.'</main>'.$footer.'</body></html>';
}
function nodenoBlogSitemapDocument(array $published,array $bank):string {
 $e='nodenoBlogEscape';$origin=nodenoBlogOrigin();$xml='<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:image="http://www.google.com/schemas/sitemap-image/1.1">';
 foreach(['tr','en','ru','ar']as $locale)$xml.='<url><loc>'.$e($origin.nodenoBlogUrl('',$locale)).'</loc></url>';
 foreach($published as $a){foreach($a['availableLocales']??['tr']as $locale)$xml.='<url><loc>'.$e($origin.nodenoBlogUrl($a['slug'],$locale)).'</loc><lastmod>'.$e($a['publishedAt']).'</lastmod><image:image><image:loc>'.$e($origin.($a['imageVariants'][$locale]??$a['image'])['url']).'</image:loc></image:image></url>';}
 return $xml.'</urlset>';
}
function nodenoBlogVisibleImage(array $published,string $url):?array {
 foreach($published as $a)foreach($a['imageVariants']??['tr'=>$a['image']]as $image)if($image['url']===$url)return $image;return null;
}
